import{_ as t,o as i,c as r,a2 as n}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Was ist ApptiveScript","description":"Die Ausdruckssprache von ApptiveGrid — wo sie vorkommt, was sie leistet und was nicht.","frontmatter":{"title":"Was ist ApptiveScript","description":"Die Ausdruckssprache von ApptiveGrid — wo sie vorkommt, was sie leistet und was nicht."},"headers":[],"relativePath":"apptivescript/was-ist-apptivescript.md","filePath":"apptivescript/was-ist-apptivescript.md","lastUpdated":1786434193000}'),s={name:"apptivescript/was-ist-apptivescript.md"};function a(d,e,c,l,o,h){return i(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="was-ist-apptivescript" tabindex="-1">Was ist ApptiveScript <a class="header-anchor" href="#was-ist-apptivescript" aria-label="Permalink to &quot;Was ist ApptiveScript&quot;">​</a></h1><p><strong>ApptiveScript</strong> ist die Ausdruckssprache von ApptiveGrid. Ein Ausdruck ist eine einzelne Rechnung, Verknüpfung oder Bedingung — er nimmt Werte, macht etwas daraus und liefert ein Ergebnis.</p><p>Sie haben ApptiveScript sehr wahrscheinlich schon benutzt, ohne es zu bemerken.</p><h2 id="jeder-filter-ist-bereits-ein-ausdruck" tabindex="-1">Jeder Filter ist bereits ein Ausdruck <a class="header-anchor" href="#jeder-filter-ist-bereits-ein-ausdruck" aria-label="Permalink to &quot;Jeder Filter ist bereits ein Ausdruck&quot;">​</a></h2><p>Wenn Sie in einer Ansicht filtern — <em>Status ist gleich Offen</em> — schreibt ApptiveGrid im Hintergrund genau das:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fieldValue(&#39;&lt;Status&gt;&#39;).isEqualTo(&#39;Offen&#39;)</span></span></code></pre></div><p>Die Bedingungen aus dem Filterdialog sind Funktionen der Sprache:</p><table tabindex="0"><thead><tr><th>Bedingung in der Oberfläche</th><th>Funktion</th></tr></thead><tbody><tr><td>ist gleich · ist nicht gleich</td><td><code>isEqualTo</code> · <code>isNotEqualTo</code></td></tr><tr><td>enthält</td><td><code>contains</code></td></tr><tr><td>ist größer als · ist kleiner als</td><td><code>greaterThan</code> · <code>smallerThan</code></td></tr><tr><td>ist leer · ist nicht leer</td><td><code>isEmpty</code> · <code>isNotEmpty</code></td></tr><tr><td>enthält eines · keines · alle von</td><td><code>includesAnyOf</code> · <code>includesNoneOf</code> · <code>includesAllOf</code></td></tr><tr><td>ist vor · ist nach</td><td><code>before</code> · <code>after</code></td></tr><tr><td>UND · ODER</td><td><code>logicalAnd</code> · <code>logicalOr</code></td></tr></tbody></table><p>Dasselbe gilt für die relativen Datumswerte: <em>heute</em> ist <code>today()</code>, <em>gestern</em> ist <code>today().subtractDays(1)</code>.</p><div class="tip custom-block"><p class="custom-block-title">Der Dialog schreibt mit</p><p>Wer einen Ausdruck von Hand schreiben will, baut ihn am schnellsten zuerst über den Dialog zusammen und sieht sich dann an, was dabei herauskommt. Die einfache Auswahl und der Ausdruck sind zwei Ansichten auf dieselbe Sache.</p></div><h2 id="wo-sie-selbst-ausdrucke-schreiben-konnen" tabindex="-1">Wo Sie selbst Ausdrücke schreiben können <a class="header-anchor" href="#wo-sie-selbst-ausdrucke-schreiben-konnen" aria-label="Permalink to &quot;Wo Sie selbst Ausdrücke schreiben können&quot;">​</a></h2><p>An sieben Stellen bietet ApptiveGrid ein Feld für einen eigenen Ausdruck an:</p><table tabindex="0"><thead><tr><th>Stelle</th><th>Wozu</th><th>Ergebnis muss sein</th></tr></thead><tbody><tr><td><strong>Formel</strong>-Spalte in einem Grid</td><td>Werte innerhalb eines Eintrags verrechnen</td><td>der gewählte Ergebnistyp</td></tr><tr><td><strong>Bedingte Sichtbarkeit</strong> eines Blocks, Bereich <em>Erweitert</em></td><td>Blöcke abhängig von Eingaben zeigen</td><td>ein Wahrheitswert</td></tr><tr><td><strong>Flow-Übergang</strong>, <em>Erweiterte Logik</em></td><td>einen Zweig nur unter Bedingungen fortsetzen</td><td>ein Wahrheitswert</td></tr><tr><td><strong>Textfelder in Flow-Schritten</strong></td><td>Werte in Betreff, Text, URL einsetzen</td><td>Text</td></tr><tr><td><strong>Filter</strong>, wenn die Auswahl nicht ausreicht</td><td>mehrere Bedingungen kombinieren</td><td>ein Wahrheitswert</td></tr><tr><td><strong>Relative Datumswerte</strong> in Filtern</td><td>„vor 7 Tagen&quot; statt eines festen Datums</td><td>ein Datum</td></tr><tr><td><strong>Einstellungsfelder vom Typ <em>Ausdruck</em></strong> in einzelnen Flow-Schritten</td><td>Wert berechnen statt eintragen</td><td>je Schritt</td></tr></tbody></table><p>Die Schreibweise ist überall dieselbe. Unterschiedlich ist nur, <strong>womit ein Ausdruck anfangen darf</strong> — das hängt davon ab, welche Werte an dieser Stelle überhaupt zur Verfügung stehen. → <a href="/apptivescript/werte-referenzieren">Werte referenzieren</a></p><h2 id="was-apptivescript-nicht-ist" tabindex="-1">Was ApptiveScript nicht ist <a class="header-anchor" href="#was-apptivescript-nicht-ist" aria-label="Permalink to &quot;Was ApptiveScript nicht ist&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Keine Programmiersprache</p><p>Es gibt <strong>keine</strong> Variablen, Schleifen, eigenen Funktionen und keine Zwischenschritte. Ein Ausdruck ist eine Zeile, die einen Wert ergibt. Wenn Sie mehrere Schritte brauchen, ist ein <a href="/flows/was-ist-ein-flow">Flow</a> das richtige Werkzeug — oder mehrere Formelspalten, die aufeinander aufbauen.</p></div><div class="warning custom-block"><p class="custom-block-title">Nicht der JavaScript-Schritt</p><p>Der Flow-Schritt <strong>JavaScript</strong> ist etwas anderes: dort läuft echtes JavaScript mit mehreren Zeilen, Variablen und Rückgabewert. ApptiveScript ist die kleine Sprache für einzelne Ausdrücke in Feldern. → <a href="/flows/aktionen">Aktionen</a></p></div><div class="danger custom-block"><p class="custom-block-title">Kein Zugriffsschutz</p><p>Eine Sichtbarkeitsregel entscheidet, was <strong>angezeigt</strong> wird — sie schützt keine Daten. Wer ausgeblendete Inhalte wirklich verbergen muss, braucht <a href="/zusammenarbeit/zugriff-beschraenken">Zugriffsbeschränkungen</a>.</p></div><h2 id="wenn-etwas-nicht-stimmt" tabindex="-1">Wenn etwas nicht stimmt <a class="header-anchor" href="#wenn-etwas-nicht-stimmt" aria-label="Permalink to &quot;Wenn etwas nicht stimmt&quot;">​</a></h2><p>Das Wichtigste zuerst: <strong>ein fehlerhafter Ausdruck macht in der Regel keinen Lärm.</strong> Er liefert nichts, und was dann passiert, ist je nach Stelle unterschiedlich:</p><table tabindex="0"><thead><tr><th>Stelle</th><th>Verhalten bei einem Ausdruck, der nicht aufgeht</th></tr></thead><tbody><tr><td><strong>Filter</strong></td><td>Der Eintrag gilt als <em>nicht zutreffend</em> und verschwindet aus der Ansicht</td></tr><tr><td><strong>Bedingte Sichtbarkeit</strong></td><td>Bei einem <em>Fehler</em> bleibt der Block sichtbar, bei einem <em>leeren Ergebnis</em> wird er ausgeblendet</td></tr><tr><td><strong>Textfeld im Flow</strong></td><td>Es wird nichts eingesetzt — der Text bleibt an dieser Stelle leer</td></tr><tr><td><strong>Formel</strong></td><td>Die Spalte bleibt leer</td></tr></tbody></table><p>Daraus folgt die wichtigste Fehlersuche-Regel: <strong>Ein Feld, das unerwartet leer bleibt oder ein Block, der immer verschwindet, ist der typische Hinweis auf einen Tippfehler im Ausdruck</strong> — nicht auf ein Rechteproblem.</p><p>Ein Name, den es nicht gibt, ist dabei kein Fehler, sondern einfach leer. <code>formValues.get(&#39;alter&#39;)</code> liefert nichts, wenn der Key in Wahrheit <code>age</code> heißt. Deshalb: Ids und Keys nie tippen, sondern einfügen. → <a href="/apptivescript/werte-referenzieren">Werte referenzieren</a></p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/apptivescript/schreibweise">Schreibweise</a> — Punkt, Klammern, Anführungszeichen</li><li><a href="/apptivescript/werte-referenzieren">Werte referenzieren</a> — womit ein Ausdruck anfängt</li><li><a href="/apptivescript/bedingungen">Bedingungen bauen</a> — Vergleiche, UND/ODER, Verzweigungen</li><li><a href="/apptivescript/editor">Der Ausdruckseditor</a> — Token-Ansicht, Picker, Beispielergebnis</li><li><a href="/referenz/apptivescript-funktionen">Funktionsreferenz</a> — alle Funktionen je Typ</li><li><a href="/grids/berechnete-felder">Berechnete Felder</a> · <a href="/seiten/sichtbarkeit">Bedingte Sichtbarkeit</a> · <a href="/flows/daten-zwischen-schritten">Daten zwischen Schritten</a></li></ul>',25)])])}const g=t(s,[["render",a]]);export{u as __pageData,g as default};
